/**
 * Access-point candidates → task locations, only through a site review.
 *
 * The register (`<campus>-campus-access-candidates.geojson`, generated by Backend
 * `tools/campus/accessCandidates.js`) proposes sidewalk points facing each footprint-only
 * destination. These tests pin the rule that keeps a proposal from becoming a delivery
 * endpoint by being generated: only a `verified` entry with a dated, attributed review is
 * admitted (`maps/campus/access/accessPointImport.js`), and only an admitted one is offered in
 * the pickup and drop lists.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const SRC = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const REPO = path.resolve(SRC, '..', '..');
const mod = (rel) => import(pathToFileURL(path.join(SRC, rel)).href);

const { importAccessPoints, ACCESS_STATUS, reviewProblems } = await mod('features/maps/campus/access/accessPointImport.js');
const { CAMPUS_GEOMETRY, resolveCampusDefinition, campusRegistryEntry } = await mod('features/maps/campus/campusRegistry.js');
const { PROVENANCE, VERIFICATION, validateCampusFeature } = await mod('features/maps/campus/campusSchema.js');
const { applyOperationalProfiles } = await mod('features/maps/campus/semantics/campusOperational.js');
const { CAMPUS_VERIFICATION, applyCampusVerification } = await mod('features/maps/campus/verification/campusVerification.js');
const { campusLocationInventory, campusTaskLocations, destinationFootprints, locationInventoryFor, LOCATION_EXCLUSION: X } =
  await mod('features/tasks/campusLocations.js');
const { buildAssignTaskRequest } = await mod('lib/taskRequest.js');
const { RNSIT_CAMPUS_ACCESS_CANDIDATES } = await mod('features/maps/campus/data/rnsit/rnsitCampusAccessCandidates.js');
const { JSSATE_BENGALURU_CAMPUS_ACCESS_CANDIDATES } = await mod(
  'features/maps/campus/data/jssate-bengaluru/jssateBengaluruCampusAccessCandidates.js'
);

const RNSIT_OFFERED = [
  'osm-node-2146315474',
  'rns-evening-college',
  'rns-first-grade-college',
  'rnsit-cyber-security-department',
  'rnsit-food-court',
  'rnsit-innovation-center',
  'rnsit-playground-2',
  'rnsit-pre-university-college',
];
const REVIEW = Object.freeze({ by: 'Project owner', on: '2026-10-22', method: 'OWNER_SITE_CHECK' });

const clone = (value) => JSON.parse(JSON.stringify(value));
const ids = (rows) => rows.map((r) => r.id).sort();
const rnsitOsm = () => CAMPUS_GEOMETRY.RNSIT.features.filter((f) => f.provenance === PROVENANCE.OPEN_DATA_IMPORT);
const rnsitBoundary = () => CAMPUS_GEOMETRY.RNSIT.features.find((f) => f.kind === 'BOUNDARY');
/** The declared point locations' names, exactly as `campusRegistry.buildCampus` passes them. */
const rnsitDeclaredNames = () =>
  CAMPUS_GEOMETRY.RNSIT.features
    .filter((f) => f.geometry?.type === 'Point' && f.provenance !== PROVENANCE.DERIVED_ACCESS_POINT)
    .map((f) => f.name);
const importRnsit = (collection) =>
  importAccessPoints(collection, {
    campusId: 'RNSIT',
    osmFeatures: rnsitOsm(),
    boundary: rnsitBoundary(),
    declaredNames: rnsitDeclaredNames(),
  });
/** Register entries by building, so a test names the place it verifies rather than an array index. */
const slotsOf = (buildingSourceId) =>
  RNSIT_CAMPUS_ACCESS_CANDIDATES.features
    .map((f, i) => [f, i])
    .filter(([f]) => f.properties.buildingSourceId === buildingSourceId)
    .map(([, i]) => i);
/** ECE Department: no other footprint and no declared location shares its name. */
const ECE = slotsOf('way/204638932');
const CANTEEN_NORTH = slotsOf('way/204638928'); // amenity=food_court, beside the Basketball Court
const CANTEEN_AUDITORIUM = slotsOf('way/1486312655'); // amenity=fast_food, shares a wall with the auditorium
const CANARA_BANK_FOOTPRINT = slotsOf('way/204638927');
/**
 * The committed RNSIT register with every review taken out — the state before any site visit — so
 * a scenario below starts from the same place whatever a reviewer has genuinely recorded.
 */
function baseline() {
  const register = clone(RNSIT_CAMPUS_ACCESS_CANDIDATES);
  for (const f of register.features) {
    if (f.properties.review || f.properties.status === ACCESS_STATUS.VERIFIED) {
      Object.assign(f.properties, { status: ACCESS_STATUS.CANDIDATE, review: null });
    }
  }
  register.features = register.features.filter((f) => f.properties.derivation?.method !== 'REVIEWER_SUPPLIED');
  return register;
}
/** The definition with no site-verified access point in it: the declared campus only. */
const declaredDefinition = () => {
  const definition = resolveCampusDefinition({ code: 'RNSIT', name: 'RNS Institute of Technology' });
  return { ...definition, features: definition.features.filter((f) => f.provenance !== PROVENANCE.DERIVED_ACCESS_POINT) };
};
/** The baseline register with the ECE entries (or the given slots) rewritten, in order. */
const withEntries = (...edits) => withSlots(ECE, ...edits);
function withSlots(slots, ...edits) {
  const register = baseline();
  edits.forEach((edit, i) => edit && Object.assign(register.features[slots[i]].properties, edit));
  return register;
}

// ── One dataset, three copies ───────────────────────────────────────────────

test('each register is the same in the repository root, the Frontend copy and its module', () => {
  for (const [dir, file, data] of [
    ['rnsit', 'rnsit-campus-access-candidates.geojson', RNSIT_CAMPUS_ACCESS_CANDIDATES],
    ['jssate-bengaluru', 'jssate-bengaluru-campus-access-candidates.geojson', JSSATE_BENGALURU_CAMPUS_ACCESS_CANDIDATES],
  ]) {
    const root = JSON.parse(fs.readFileSync(path.join(REPO, file), 'utf8'));
    const copy = JSON.parse(fs.readFileSync(path.join(SRC, 'features/maps/campus/data', dir, file), 'utf8'));
    assert.deepEqual(copy, root, `${file}: regenerate with Backend tools/campus/generateAccessCandidates.js --write`);
    assert.deepEqual(data, root, `${file}: the module is not the register`);
  }
});

test('the register covers exactly the dashboard\'s destination footprints — one list of buildings', () => {
  for (const [campus, register] of [['RNSIT', RNSIT_CAMPUS_ACCESS_CANDIDATES], ['jssate-bengaluru', JSSATE_BENGALURU_CAMPUS_ACCESS_CANDIDATES]]) {
    assert.deepEqual(
      register.buildings.map((b) => b.buildingFeatureId).sort(),
      destinationFootprints(campus).map((f) => f.featureId).sort(),
      campus
    );
  }
});

// ── The committed state: only a reviewed, admitted entry is ever offered ────
//
// These hold whatever a reviewer has recorded: before any site review (0 verified) and after
// genuine ones. A `verified` entry the importer refuses fails here, so a reviewer's mistake (an
// unlabelled canteen, a missing date) cannot sit in the register unnoticed.

const REGISTERS = [['RNSIT', RNSIT_CAMPUS_ACCESS_CANDIDATES], ['jssate-bengaluru', JSSATE_BENGALURU_CAMPUS_ACCESS_CANDIDATES]];
const isVerified = (f) => f.properties.status === ACCESS_STATUS.VERIFIED;
/** The locations offered that are declared points, not site-verified access points. */
const declaredOf = (rows) => rows.filter((l) => l.servesFeatureId === null);

test('an unverified entry never appears in the pickup or drop list; a verified one only with a valid review', () => {
  for (const [campus, register] of REGISTERS) {
    assert.ok(register.features.length > 0, campus);
    assert.deepEqual(CAMPUS_GEOMETRY[campus].accessPoints.invalid, [], `${campus}: a verified entry was refused — see audit:locations`);
    const { locations } = campusTaskLocations(campus);
    const offered = new Map(locations.map((l) => [l.id, l]));
    for (const f of register.features) {
      const [lon, lat] = f.geometry.coordinates;
      if (isVerified(f)) {
        assert.deepEqual(reviewProblems(f.properties.review), [], f.properties.id);
        assert.ok(offered.has(f.properties.id), `${f.properties.id} verified but not offered`);
        assert.deepEqual([offered.get(f.properties.id).lon, offered.get(f.properties.id).lat], [lon, lat]);
        continue;
      }
      assert.ok(!offered.has(f.properties.id), f.properties.id);
      for (const l of locations) assert.ok(!(l.lon === lon && l.lat === lat), `${f.properties.id} offered under another id`);
    }
    // Everything offered that is not a declared point is a verified register entry.
    const verifiedIds = new Set(register.features.filter(isVerified).map((f) => f.properties.id));
    for (const l of locations.filter((x) => x.servesFeatureId !== null)) assert.ok(verifiedIds.has(l.id), l.id);
  }
  assert.deepEqual(ids(declaredOf(campusTaskLocations('RNSIT').locations)), RNSIT_OFFERED);
  assert.deepEqual(declaredOf(campusTaskLocations('jssate-bengaluru').locations), []);
});

test('every register entry is accounted for in the inventory, by status', () => {
  for (const [campus, register] of REGISTERS) {
    const inventory = campusLocationInventory(campus);
    assert.equal(inventory.offered.length + inventory.excluded.length, inventory.sourceFeatureCount, campus);
    const reasonOf = new Map(inventory.excluded.map((r) => [r.id, r.reason]));
    const offeredIds = new Set(inventory.offered.map((l) => l.id));
    for (const f of register.features) {
      if (isVerified(f)) {
        assert.ok(offeredIds.has(f.properties.id), f.properties.id);
        continue;
      }
      const expected = f.properties.status === ACCESS_STATUS.REJECTED ? X.REJECTED_ACCESS_CANDIDATE : X.UNVERIFIED_ACCESS_CANDIDATE;
      assert.equal(reasonOf.get(f.properties.id), expected, f.properties.id);
    }
    // A footprint is served exactly by its verified entries.
    for (const footprint of destinationFootprints(campus)) {
      const mine = register.features.filter((f) => isVerified(f) && f.properties.buildingFeatureId === footprint.featureId);
      assert.deepEqual(footprint.servedBy.sort(), mine.map((f) => f.properties.id).sort(), footprint.featureId);
    }
  }
});

// ── The importer: only a reviewed `verified` entry is admitted ──────────────

test('candidate and needs_review entries are pending, however good they look', () => {
  const register = baseline();
  const result = importRnsit(register);
  assert.deepEqual(result.features, []);
  assert.deepEqual(result.invalid, []);
  const clean = register.features.find((f) => f.properties.status === ACCESS_STATUS.CANDIDATE);
  // Inside the boundary, on the sidewalk, routable — and still not admitted.
  assert.equal(clean.properties.validation.deliveryDomain, 'INSIDE');
  assert.equal(clean.properties.measurements.physicalAccessM, 0);
  assert.ok(result.pending.some((p) => p.id === clean.properties.id));
  assert.equal(result.pending.length + result.rejected.length, register.features.length);
});

test('a verified entry with a site review becomes a campus feature that says where it came from', () => {
  const result = importRnsit(withEntries({ status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, note: 'ramp to the door' } }));
  assert.equal(result.features.length, 1);
  const [feature] = result.features;
  const entry = RNSIT_CAMPUS_ACCESS_CANDIDATES.features[ECE[0]];
  assert.equal(feature.id, entry.properties.id);
  assert.equal(feature.name, entry.properties.buildingName);
  assert.equal(feature.servesFeatureId, entry.properties.buildingFeatureId);
  assert.deepEqual(feature.geometry.coordinates, entry.geometry.coordinates, 'coordinate unchanged');
  assert.equal(feature.provenance, PROVENANCE.DERIVED_ACCESS_POINT);
  assert.equal(feature.verification, VERIFICATION.VERIFIED_BY_USER);
  assert.equal(feature.verifiedBy, 'Project owner');
  assert.equal(feature.verifiedOn, '2026-10-22');
  assert.deepEqual(validateCampusFeature(feature, feature.id), []);
  // A survey earns VERIFIED; an owner's check never does.
  const surveyed = importRnsit(withEntries({ status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, method: 'SURVEY' } }));
  assert.equal(surveyed.features[0].verification, VERIFICATION.VERIFIED);
});

test('`verified` without a real review, off campus, malformed, or for an unknown building is refused by name', () => {
  const cases = [
    ['no review', { status: ACCESS_STATUS.VERIFIED, review: null }, /no review/],
    ['no reviewer', { status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, by: ' ' } }, /review\.by/],
    ['bad date', { status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, on: '22/10/2026' } }, /review\.on/],
    ['unknown method', { status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, method: 'LOOKED_AT_A_MAP' } }, /review\.method/],
    ['unknown building', { status: ACCESS_STATUS.VERIFIED, review: REVIEW, buildingFeatureId: 'osm-way-1', buildingSourceId: 'way/1' }, /names no footprint/],
    ['other campus', { status: ACCESS_STATUS.VERIFIED, review: REVIEW, campusId: 'jssate-bengaluru' }, /not RNSIT/],
    ['unknown status', { status: 'approved', review: REVIEW }, /unknown status/],
  ];
  for (const [label, edit, pattern] of cases) {
    const result = importRnsit(withEntries(edit));
    assert.deepEqual(result.features, [], label);
    assert.equal(result.invalid.length, 1, label);
    assert.match(result.invalid[0].problems.join('; '), pattern, label);
  }

  const geometryCases = [
    ['outside the boundary', [77.5946, 12.9716], /outside the campus boundary/],
    ['transposed [lat, lon]', null, /outside the campus boundary/],
    ['NaN', [Number.NaN, 12.9], /finite/],
  ];
  for (const [label, coordinates, pattern] of geometryCases) {
    const register = withEntries({ status: ACCESS_STATUS.VERIFIED, review: REVIEW });
    const g = register.features[ECE[0]].geometry;
    g.coordinates = coordinates || [g.coordinates[1], g.coordinates[0]];
    const result = importRnsit(register);
    assert.deepEqual(result.features, [], label);
    assert.match(result.invalid[0].problems.join('; '), pattern, label);
  }
});

test('duplicates: one id once; a second verified point for one building needs its own label', () => {
  const register = withEntries({ status: ACCESS_STATUS.VERIFIED, review: REVIEW });
  register.features.push(clone(register.features[ECE[0]]));
  const twice = importRnsit(register);
  assert.equal(twice.features.length, 1);
  assert.match(twice.invalid[0].problems.join('; '), /already admitted/);

  // Two candidates of the same footprint (ECE Department).
  const unlabelled = importRnsit(withEntries({ status: ACCESS_STATUS.VERIFIED, review: REVIEW }, { status: ACCESS_STATUS.VERIFIED, review: REVIEW }));
  assert.equal(unlabelled.features.length, 1);
  assert.match(unlabelled.invalid[0].problems.join('; '), /distinct review\.label/);
  const labelled = importRnsit(
    withEntries(
      { status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, label: 'east door' } },
      { status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, label: 'west door' } }
    )
  );
  assert.deepEqual(labelled.features.map((f) => f.name), ['ECE Department — east door', 'ECE Department — west door']);
  // Labels that differ only in case or spacing are the same name to an operator.
  const sameName = importRnsit(
    withEntries(
      { status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, label: 'East door' } },
      { status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, label: ' east  door ' } }
    )
  );
  assert.equal(sameName.features.length, 1);
});

// ── Display names are unique across the campus (the two "Canteen" footprints) ──

test('RNSIT maps two different buildings as "Canteen"; neither is offered as plain "Canteen"', () => {
  const canteens = rnsitOsm().filter((f) => f.name === 'Canteen' && f.geometry.type === 'Polygon');
  assert.deepEqual(canteens.map((f) => f.id).sort(), ['osm-way-1486312655', 'osm-way-204638928']);
  // One verified, unlabelled: refused even though the other canteen is not verified.
  const one = importRnsit(withSlots(CANTEEN_NORTH, { status: ACCESS_STATUS.VERIFIED, review: REVIEW }));
  assert.deepEqual(one.features, []);
  assert.match(one.invalid[0].problems.join('; '), /"Canteen" names 2 footprints on this campus/);
  // Both verified, unlabelled: both refused — no two indistinguishable options.
  const both = withSlots(CANTEEN_NORTH, { status: ACCESS_STATUS.VERIFIED, review: REVIEW });
  Object.assign(both.features[CANTEEN_AUDITORIUM[0]].properties, { status: ACCESS_STATUS.VERIFIED, review: REVIEW });
  const result = importRnsit(both);
  assert.deepEqual(result.features, []);
  assert.equal(result.invalid.length, 2);
});

test('two verified points on different footprints can never share a display name; every one in the clash is refused', () => {
  const register = withSlots(CANTEEN_NORTH, { status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, label: 'North' } });
  Object.assign(register.features[CANTEEN_AUDITORIUM[0]].properties, {
    status: ACCESS_STATUS.VERIFIED,
    review: { ...REVIEW, label: 'north' },
  });
  const result = importRnsit(register);
  assert.deepEqual(result.features, [], 'not first-come-first-served: neither "Canteen — North" is admitted');
  assert.equal(result.invalid.length, 2);
  for (const row of result.invalid) assert.match(row.problems.join('; '), /would also name an access point of/);
});

test('distinct explicit labels are accepted, and both are offered to pickup and drop', () => {
  const register = withSlots(CANTEEN_NORTH, {
    status: ACCESS_STATUS.VERIFIED,
    review: { ...REVIEW, label: 'near Basketball Court' },
  });
  Object.assign(register.features[CANTEEN_AUDITORIUM[0]].properties, {
    status: ACCESS_STATUS.VERIFIED,
    review: { ...REVIEW, label: 'beside Auditorium' },
  });
  const admitted = importRnsit(register);
  assert.deepEqual(admitted.invalid, []);
  assert.deepEqual(admitted.features.map((f) => f.name).sort(), ['Canteen — beside Auditorium', 'Canteen — near Basketball Court']);

  const definition = declaredDefinition();
  const inventory = locationInventoryFor({
    ...definition,
    features: [...definition.features, ...applyOperationalProfiles(admitted.features)],
    accessPoints: { ...definition.accessPoints, pending: admitted.pending, rejected: admitted.rejected, invalid: admitted.invalid },
  });
  assert.equal(inventory.offered.length, RNSIT_OFFERED.length + 2);
  const names = inventory.offered.map((l) => l.name.toLowerCase());
  assert.equal(new Set(names).size, names.length, 'every offered name is distinct');
});

test('an access point may not repeat a declared location\'s name (the Canara Bank footprint vs the bank\'s OSM point)', () => {
  assert.ok(rnsitDeclaredNames().includes('Canara Bank'));
  const plain = importRnsit(withSlots(CANARA_BANK_FOOTPRINT, { status: ACCESS_STATUS.VERIFIED, review: REVIEW }));
  assert.deepEqual(plain.features, []);
  assert.match(plain.invalid[0].problems.join('; '), /already the name of a declared location/);
  const labelled = importRnsit(
    withSlots(CANARA_BANK_FOOTPRINT, { status: ACCESS_STATUS.VERIFIED, review: { ...REVIEW, label: 'bank building' } })
  );
  assert.deepEqual(labelled.features.map((f) => f.name), ['Canara Bank — bank building']);
});

test('unverified canteen candidates stay excluded, and the declared locations are unchanged', () => {
  const result = importRnsit(clone(RNSIT_CAMPUS_ACCESS_CANDIDATES));
  assert.deepEqual(result.invalid, []);
  const pending = new Set(result.pending.map((p) => p.id));
  for (const i of [...CANTEEN_NORTH, ...CANTEEN_AUDITORIUM]) {
    const entry = RNSIT_CAMPUS_ACCESS_CANDIDATES.features[i];
    if (entry.properties.status === ACCESS_STATUS.VERIFIED) continue; // only once genuinely reviewed, with a label
    assert.ok(pending.has(entry.properties.id), entry.properties.id);
    assert.ok(!campusTaskLocations('RNSIT').locations.some((l) => l.id === entry.properties.id), entry.properties.id);
  }
  // The registry imports the same register with the same rule: it admits exactly the verified
  // entries, refuses none, and the declared locations are the same eight.
  const verified = RNSIT_CAMPUS_ACCESS_CANDIDATES.features.filter((f) => f.properties.status === ACCESS_STATUS.VERIFIED);
  assert.equal(CAMPUS_GEOMETRY.RNSIT.accessPoints.admittedFeatureCount, verified.length);
  assert.deepEqual(CAMPUS_GEOMETRY.RNSIT.accessPoints.invalid, []);
  assert.deepEqual(ids(declaredOf(campusTaskLocations('RNSIT').locations)), RNSIT_OFFERED);
  assert.equal(campusTaskLocations('RNSIT').locations.length, RNSIT_OFFERED.length + verified.length);
});

// ── End to end through the inventory: a verified point is offered to both ends ──

test('a verified access point is offered once, to pickup and drop alike, and serves its footprint', () => {
  const definition = declaredDefinition();
  const register = withEntries({}, {}, { status: ACCESS_STATUS.VERIFIED, review: REVIEW }); // the third ECE candidate
  const admitted = importRnsit(register);
  const record = CAMPUS_VERIFICATION.RNSIT;
  const features = applyCampusVerification(applyOperationalProfiles(admitted.features), record).features;
  // The campus's blanket owner check does not cover a derived point: its verification is its own review.
  assert.ok(!record.covers.includes(PROVENANCE.DERIVED_ACCESS_POINT));
  assert.equal(features[0].verifiedOn, '2026-10-22');

  const inventory = locationInventoryFor({
    ...definition,
    features: [...definition.features, ...features],
    accessPoints: { ...definition.accessPoints, pending: admitted.pending, rejected: admitted.rejected, invalid: admitted.invalid },
  });
  const entry = register.features[ECE[2]].properties;
  const offered = inventory.offered.find((l) => l.id === entry.id);
  assert.ok(offered, 'offered');
  assert.equal(offered.name, entry.buildingName);
  assert.equal(inventory.offered.length, RNSIT_OFFERED.length + 1);
  const footprint = inventory.excluded.find((r) => r.id === entry.buildingFeatureId);
  assert.equal(footprint.reason, X.SERVED_BY_ACCESS_POINT);
  assert.deepEqual(footprint.servedBy, [entry.id]);
  // The other candidates are still not offered.
  assert.equal(inventory.excluded.filter((r) => r.reason === X.UNVERIFIED_ACCESS_CANDIDATE).length, register.features.length - 1);
  assert.equal(inventory.offered.length + inventory.excluded.length, inventory.sourceFeatureCount);
});

// ── JSSATE ──────────────────────────────────────────────────────────────────

test('JSSATE: a verified candidate still cannot be submitted, because the campus has no operating region', () => {
  const register = clone(JSSATE_BENGALURU_CAMPUS_ACCESS_CANDIDATES);
  const entry = register.features.find((f) => f.properties.status === ACCESS_STATUS.CANDIDATE);
  Object.assign(entry.properties, { status: ACCESS_STATUS.VERIFIED, review: REVIEW });
  const jssate = CAMPUS_GEOMETRY['jssate-bengaluru'];
  const admitted = importAccessPoints(register, {
    campusId: 'jssate-bengaluru',
    osmFeatures: jssate.features.filter((f) => f.provenance === PROVENANCE.OPEN_DATA_IMPORT),
    boundary: jssate.features.find((f) => f.kind === 'BOUNDARY'),
  });
  assert.equal(admitted.features.length, 1);
  // …and the same entry is refused by the other campus.
  assert.match(importRnsit(register).invalid[0].problems.join('; '), /not RNSIT/);

  assert.equal(campusRegistryEntry('jssate-bengaluru').regionId, null);
  const [lon, lat] = entry.geometry.coordinates;
  assert.throws(
    () =>
      buildAssignTaskRequest({
        campusId: 'jssate-bengaluru', pickup: 'A', pickupLat: lat, pickupLon: lon, drop: 'B', dropLat: lat, dropLon: lon,
        payload: { massKg: 1, massToleranceKg: 0.1 }, requestedChassisType: 'ROVER',
      }),
    /no operating region/
  );
});
